                o.getBasisWeightFrom(), o.getBasisWeightTo(),
                o.getAshLevelFrom(), o.getAshLevelTo(),
                o.getStatus(), o.getAppliedRequestId(), Timestamp.valueOf(o.getAppliedAt()));
    }

