    public void updateDecision(TransitionOrder o) {
        jdbc.update("""
                        UPDATE transition_order
                        SET basis_weight_delta_pct = ?, ash_level_delta = ?,
                            direct_switch = ?, wire_flush = ?,
                            status = ?, decided_at = ?
                        WHERE order_no = ?
                        """,
